import { businessConfig, PLACEHOLDERS } from "@/config/business";

export function isWhatsAppConfigured(number: string = businessConfig.whatsapp): boolean {
  const trimmed = number.trim();
  if (!trimmed) return false;
  if (trimmed.toLowerCase() === PLACEHOLDERS.whatsapp.toLowerCase()) return false;
  if (/x/i.test(trimmed)) return false;

  const digits = trimmed.replace(/\D/g, "");
  if (digits.length < 10 || digits.length > 15) return false;
  if (!/^[1-9]\d{9,14}$/.test(digits)) return false;

  return true;
}

export function getConfiguredWhatsAppNumber(): string | null {
  if (!isWhatsAppConfigured()) return null;
  return businessConfig.whatsapp.replace(/\D/g, "");
}

export function buildWhatsAppUrl(message: string): string | null {
  const phone = getConfiguredWhatsAppNumber();
  if (!phone) return null;
  return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
}

export function openWhatsApp(message: string): boolean {
  const url = buildWhatsAppUrl(message);
  if (!url || typeof window === "undefined") return false;
  window.open(url, "_blank", "noopener,noreferrer");
  return true;
}

